public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // Validate inputs
    if (a == null || b == null) {
        return false;
    }
    if (count < 0) {
        return false;
    }
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

